"""
views/svg_assets.py — shared SVG/Cairo assets for BulwarkOS UI.

Icons are rendered via Gtk.DrawingArea + Cairo so they automatically
inherit the theme foreground colour — they change correctly between
light and dark mode without any additional logic.

Shield images are written to a temp SVG file (the only reliable way to
load a complex multi-path SVG in GTK4 without librsvg bindings), but the
colour is passed in explicitly so callers can match the theme manually.
"""

import os
import math
import tempfile

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Gdk", "4.0")
from gi.repository import Gtk, Gdk

