def _ticon(inner: str, vb: str = "0 0 24 24") -> str:
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{vb}" '
        f'width="28" height="28" fill="white">{inner}</svg>'
    )


