def make_template_icon_image(template_id: str, pixel_size: int = 28) -> Gtk.Image:
    svg = TEMPLATE_ICONS.get(template_id)
    if not svg:
        img = Gtk.Image.new_from_icon_name("computer-symbolic")
        img.set_pixel_size(pixel_size)
        return img
    tmp = tempfile.NamedTemporaryFile(suffix=".svg", delete=False)
    try:
        tmp.write(svg.encode())
        tmp.flush()
        img = Gtk.Image.new_from_file(tmp.name)
        img.set_pixel_size(pixel_size)
    finally:
        tmp.close()
        try:
            os.unlink(tmp.name)
        except OSError:
            pass
    return img


# ---------------------------------------------------------------------------
# Sidebar icons — Gtk.DrawingArea with Cairo
#
# Rendered at draw time using the widget's actual foreground colour from
# Gtk.StyleContext, so they automatically adapt to light/dark mode switches
# without any manual colour management.
#
# Each entry is a callable: (cr, w, h) → None
# cr   = cairo.Context already scaled so the icon fills the widget area
# w, h = widget pixel dimensions (typically 16x16)
# ---------------------------------------------------------------------------

def _sidebar_draw_fn(fn):
    """Wrap a draw function so it queries foreground colour at draw time."""
    def draw(da, cr, width, height):
        # Get the current foreground colour from the widget style
        ctx  = da.get_style_context()
        rgba = ctx.get_color()
        cr.set_source_rgba(rgba.red, rgba.green, rgba.blue, rgba.alpha)
        # Scale coordinate system so icon path can use 0-1 normalised coords
        cr.save()
        cr.scale(width, height)
        fn(cr)
        cr.restore()
    return draw


# Each path function draws on a 0..1 × 0..1 canvas.
# Paths are simplified versions of the Material Design icons, hand-normalised.

def _draw_ethernet(cr):
    """
    Ethernet port icon from Ethernet_Port.svg (potrace).
    Original coords: 800x800, Y-flipped (potrace bottom-origin).
    Normalised here to 0..1 x 0..1 with Y corrected.
    The three rectangles represent the RJ45 connector body and its ports.
    """
    # We convert the potrace 800x800 space manually.
    # potrace group: translate(0,800) scale(0.1,-0.1)
    # So point (px, py) in path → screen (px*0.1, 800 - py*0.1)
    # We then normalise to 0..1 by dividing by 800.
    # screen_x = px * 0.1 / 800 = px / 8000
    # screen_y = (800 - py * 0.1) / 800 = 1 - py / 8000

    # Rather than converting the full complex path, draw a clean
    # semantic equivalent of the Ethernet_Port icon:
    # — outer rectangle (connector body)
    # — inner rectangle (port opening)
    # — three vertical pins inside

    cr.set_line_width(0.0)

    # Outer body — rounded rectangle spanning full width, upper 60%
    x0, y0, w, h = 0.08, 0.05, 0.84, 0.60
    r = 0.06
    cr.move_to(x0 + r, y0)
    cr.line_to(x0 + w - r, y0)
    cr.arc(x0 + w - r, y0 + r, r, -math.pi/2, 0)
    cr.line_to(x0 + w, y0 + h - r)
    cr.arc(x0 + w - r, y0 + h - r, r, 0, math.pi/2)
    cr.line_to(x0 + r, y0 + h)
    cr.arc(x0 + r, y0 + h - r, r, math.pi/2, math.pi)
    cr.line_to(x0, y0 + r)
    cr.arc(x0 + r, y0 + r, r, math.pi, 3*math.pi/2)
    cr.close_path()
    cr.fill()

    # Cut out the port opening (inset rectangle) in the lower half of body
    # Draw in background colour — get it from context not available here,
    # so instead draw a slightly inset rectangle in the background using
    # operator CLEAR (works on transparent surfaces)
    cr.set_operator(1)  # CAIRO_OPERATOR_CLEAR
    ix, iy, iw, ih = 0.18, 0.30, 0.64, 0.28
    ri = 0.03
    cr.move_to(ix + ri, iy)
    cr.line_to(ix + iw - ri, iy)
    cr.arc(ix + iw - ri, iy + ri, ri, -math.pi/2, 0)
    cr.line_to(ix + iw, iy + ih)
    cr.line_to(ix, iy + ih)
    cr.line_to(ix, iy + ri)
    cr.arc(ix + ri, iy + ri, ri, math.pi, 3*math.pi/2)
    cr.close_path()
    cr.fill()
    cr.set_operator(2)  # CAIRO_OPERATOR_OVER

    # Cable plug stem — rectangle below body
    cr.rectangle(0.38, 0.65, 0.24, 0.22)
    cr.fill()

    # Three pins at bottom of stem
    pin_y  = 0.87
    pin_h  = 0.08
    pin_w  = 0.06
    for px in (0.28, 0.47, 0.66):
        cr.rectangle(px, pin_y, pin_w, pin_h)
        cr.fill()


def _draw_firewall(cr):
    """Shield shape for sys-firewall."""
    # Shield: M 0.5,0.05 L 0.05,0.25 V 0.55 C 0.05,0.8 0.5,0.95 0.5,0.95
    #         C 0.5,0.95 0.95,0.8 0.95,0.55 V 0.25 Z
    cr.move_to(0.5,  0.04)
    cr.line_to(0.05, 0.22)
    cr.line_to(0.05, 0.55)
    cr.curve_to(0.05, 0.80,  0.5, 0.96, 0.5, 0.96)
    cr.curve_to(0.5,  0.96, 0.95, 0.80, 0.95, 0.55)
    cr.line_to(0.95, 0.22)
    cr.close_path()
    cr.fill()
    # Inner shield highlight (cut out lighter area)
    cr.set_operator(1)  # CLEAR
    cr.move_to(0.5,  0.18)
    cr.line_to(0.18, 0.30)
    cr.line_to(0.18, 0.54)
    cr.curve_to(0.18, 0.72, 0.5, 0.84, 0.5, 0.84)
    cr.curve_to(0.5,  0.84, 0.82, 0.72, 0.82, 0.54)
    cr.line_to(0.82, 0.30)
    cr.close_path()
    cr.fill()
    cr.set_operator(2)  # OVER


def _draw_home(cr):
    """House for personal VM."""
    # Roof triangle
    cr.move_to(0.5,  0.08)
    cr.line_to(0.0,  0.52)
    cr.line_to(0.15, 0.52)
    cr.line_to(0.15, 0.92)
    cr.line_to(0.42, 0.92)
    cr.line_to(0.42, 0.65)
    cr.line_to(0.58, 0.65)
    cr.line_to(0.58, 0.92)
    cr.line_to(0.85, 0.92)
    cr.line_to(0.85, 0.52)
    cr.line_to(1.0,  0.52)
    cr.close_path()
    cr.fill()


def _draw_briefcase(cr):
    """Briefcase for work VM."""
    # Handle
    cr.set_line_width(0.07)
    cr.arc(0.5, 0.28, 0.18, math.pi, 0)
    cr.stroke()
    cr.set_line_width(0)
    # Body
    r = 0.05
    x, y, w, h = 0.08, 0.35, 0.84, 0.52
    cr.move_to(x+r, y)
    cr.line_to(x+w-r, y); cr.arc(x+w-r, y+r, r, -math.pi/2, 0)
    cr.line_to(x+w, y+h-r); cr.arc(x+w-r, y+h-r, r, 0, math.pi/2)
    cr.line_to(x+r, y+h); cr.arc(x+r, y+h-r, r, math.pi/2, math.pi)
    cr.line_to(x, y+r); cr.arc(x+r, y+r, r, math.pi, 3*math.pi/2)
    cr.close_path()
    cr.fill()
    # Horizontal centre line
    cr.set_operator(1)
    cr.rectangle(0.08, 0.59, 0.84, 0.05)
    cr.fill()
    cr.set_operator(2)


def _draw_bank(cr):
    """Pillars / bank for banking VM."""
    # Roof triangle
    cr.move_to(0.5, 0.05); cr.line_to(0.02, 0.30); cr.line_to(0.98, 0.30)
    cr.close_path(); cr.fill()
    # Three pillars
    for px in (0.12, 0.44, 0.76):
        cr.rectangle(px, 0.33, 0.12, 0.46)
        cr.fill()
    # Base bar
    cr.rectangle(0.02, 0.82, 0.96, 0.10)
    cr.fill()


def _draw_code(cr):
    """Code brackets < > for development VM."""
    cr.set_line_width(0.12)
    cr.set_line_join(0)  # CAIRO_LINE_JOIN_MITER
    # Left bracket <
    cr.move_to(0.42, 0.20); cr.line_to(0.12, 0.50); cr.line_to(0.42, 0.80)
    cr.stroke()
    # Right bracket >
    cr.move_to(0.58, 0.20); cr.line_to(0.88, 0.50); cr.line_to(0.58, 0.80)
    cr.stroke()
    cr.set_line_width(0)


def _draw_play(cr):
    """Play circle for media VM."""
    # Circle
    cr.arc(0.5, 0.5, 0.46, 0, 2*math.pi); cr.fill()
    # Play triangle cutout
    cr.set_operator(1)
    cr.move_to(0.38, 0.28); cr.line_to(0.38, 0.72); cr.line_to(0.74, 0.50)
    cr.close_path(); cr.fill()
    cr.set_operator(2)


def _draw_trash(cr):
    """Trash can for disposable VM."""
    # Lid
    cr.rectangle(0.10, 0.10, 0.80, 0.12); cr.fill()
    # Handle on lid
    cr.set_operator(1)
    cr.rectangle(0.35, 0.05, 0.30, 0.10); cr.fill()
    cr.set_operator(2)
    # Body
    r = 0.04
    x, y, w, h = 0.15, 0.26, 0.70, 0.66
    cr.move_to(x+r, y)
    cr.line_to(x+w-r, y); cr.arc(x+w-r, y+r, r, -math.pi/2, 0)
    cr.line_to(x+w, y+h-r); cr.arc(x+w-r, y+h-r, r, 0, math.pi/2)
    cr.line_to(x+r, y+h); cr.arc(x+r, y+h-r, r, math.pi/2, math.pi)
    cr.line_to(x, y+r); cr.arc(x+r, y+r, r, math.pi, 3*math.pi/2)
    cr.close_path(); cr.fill()
    # Three vertical lines inside body
    cr.set_operator(1)
    for lx in (0.35, 0.49, 0.63):
        cr.rectangle(lx, 0.33, 0.06, 0.50)
        cr.fill()
    cr.set_operator(2)


def _draw_gamepad(cr):
    """Gamepad for gaming VM."""
    # Body — wide oval
    cr.move_to(0.5,  0.25)
    cr.curve_to(0.80, 0.25, 0.95, 0.40, 0.95, 0.55)
    cr.curve_to(0.95, 0.75, 0.78, 0.85, 0.65, 0.80)
    cr.line_to(0.5,  0.70)
    cr.line_to(0.35, 0.80)
    cr.curve_to(0.22, 0.85, 0.05, 0.75, 0.05, 0.55)
    cr.curve_to(0.05, 0.40, 0.20, 0.25, 0.5, 0.25)
    cr.close_path(); cr.fill()
    # D-pad cross (left side)
    cr.set_operator(1)
    cr.rectangle(0.12, 0.44, 0.26, 0.08); cr.fill()
    cr.rectangle(0.21, 0.36, 0.08, 0.24); cr.fill()
    # Two buttons (right side)
    cr.arc(0.70, 0.44, 0.05, 0, 2*math.pi); cr.fill()
    cr.arc(0.82, 0.52, 0.05, 0, 2*math.pi); cr.fill()
    cr.set_operator(2)


def _draw_computer(cr):
    """Generic monitor/computer."""
    # Screen
    r = 0.05
    x, y, w, h = 0.05, 0.08, 0.90, 0.64
    cr.move_to(x+r, y)
    cr.line_to(x+w-r, y); cr.arc(x+w-r, y+r, r, -math.pi/2, 0)
    cr.line_to(x+w, y+h-r); cr.arc(x+w-r, y+h-r, r, 0, math.pi/2)
    cr.line_to(x+r, y+h); cr.arc(x+r, y+h-r, r, math.pi/2, math.pi)
    cr.line_to(x, y+r); cr.arc(x+r, y+r, r, math.pi, 3*math.pi/2)
    cr.close_path(); cr.fill()
    # Screen bezel cutout
    cr.set_operator(1)
    cr.rectangle(0.12, 0.15, 0.76, 0.48); cr.fill()
    cr.set_operator(2)
    # Stand
    cr.rectangle(0.40, 0.72, 0.20, 0.14); cr.fill()
    # Base
    cr.rectangle(0.22, 0.86, 0.56, 0.08); cr.fill()


# Map from icon-name → draw function
_SIDEBAR_DRAW_FNS: dict[str, callable] = {
    "network-wired-symbolic":      _draw_ethernet,
    "firewall-symbolic":           _draw_firewall,
    "user-home-symbolic":          _draw_home,
    "briefcase-symbolic":          _draw_briefcase,
    "bank-symbolic":               _draw_bank,
    "code-symbolic":               _draw_code,
    "multimedia-player-symbolic":  _draw_play,
    "user-trash-symbolic":         _draw_trash,
    "applications-games-symbolic": _draw_gamepad,
    "computer-symbolic":           _draw_computer,
}


def make_sidebar_icon(icon_name: str, size: int = 16) -> Gtk.Widget:
    """
    Return a theme-adaptive sidebar icon widget.

    Uses Gtk.DrawingArea + Cairo so the icon colour is queried from
    Gtk.StyleContext at every draw call — it automatically switches
    between light and dark mode with no additional logic required.

    Falls back to Gtk.Image.new_from_icon_name() for unknown icon names.
    """
    draw_fn = _SIDEBAR_DRAW_FNS.get(icon_name)
    if draw_fn is None:
        img = Gtk.Image.new_from_icon_name(icon_name)
        img.set_pixel_size(size)
        return img

    da = Gtk.DrawingArea()
    da.set_size_request(size, size)
    da.set_valign(Gtk.Align.CENTER)
    da.set_halign(Gtk.Align.CENTER)
    da.set_draw_func(_sidebar_draw_fn(draw_fn))
    return da
